mapper.select:
select count(1)
from lf_report
where reporter_id = #{reporterId}
  and target_type = #{targetType}
  and target_id = #{targetId}
  and status = 'PENDING'

select report_id, reporter_id, target_type, target_id, reason_code, description, status, case_id, handler_id, handle_result, handled_time, create_time from lf_report
status = #{status} and target_type = #{targetType}
order by create_time desc, report_id desc
